using Movers.Api.Configuration;
using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Movers.Api.Contracts.Pickups;using Movers.Services.Pickups;using Movers.Services.Security;
namespace Movers.Api.Controllers;
[ApiController,Authorize(Policy=SecurityPermissions.OperationsManage),Route("api/pickups")]
public sealed class PickupsController(IPickupService service,PublicLinks links):ControllerBase{
 [HttpPut("statuses/{id:guid}")]public async Task<ActionResult> UpdateStatus(Guid id,SavePickupStatusRequest r,CancellationToken t)=>await RunNullable(()=>service.UpdateStatus(id,r.Command(),t));[HttpPatch("statuses/{id:guid}/status")]public async Task<ActionResult> StatusActive(Guid id,SetPickupMasterStatusRequest r,CancellationToken t)=>await RunNullable(()=>service.SetStatusActive(id,r.IsActive,t));
 [HttpPut("vehicles/{id:guid}")]public async Task<ActionResult> UpdateVehicle(Guid id,SaveVehicleRequest r,CancellationToken t)=>await RunNullable(()=>service.UpdateVehicle(id,r.Command(),t));[HttpPatch("vehicles/{id:guid}/status")]public async Task<ActionResult> VehicleActive(Guid id,SetPickupMasterStatusRequest r,CancellationToken t)=>await RunNullable(()=>service.SetVehicleActive(id,r.IsActive,t));
 [HttpPut("{id:guid}")]public async Task<ActionResult> Update(Guid id,SavePickupRequest r,CancellationToken t)=>await RunNullable(()=>service.Update(id,r.Command(),t));
 /// <summary>Advanced search: ?search=&amp;sort=&amp;desc=&amp;skip=&amp;take= (plus statusId and customerState on the register).</summary>
 [HttpGet("search")]public async Task<ActionResult> Search([FromQuery]Movers.Services.Common.ListQuery query,[FromQuery]Guid? statusId,[FromQuery]string? customerState,CancellationToken t)=>await Run(()=>service.Search(new PickupListFilter(statusId,customerState),query,t));
 [HttpGet("statuses/search")]public async Task<ActionResult> SearchStatuses([FromQuery]Movers.Services.Common.ListQuery query,CancellationToken t)=>await Run(()=>service.SearchStatuses(query,t));[HttpGet("vehicles/search")]public async Task<ActionResult> SearchVehicles([FromQuery]Movers.Services.Common.ListQuery query,CancellationToken t)=>await Run(()=>service.SearchVehicles(query,t));
 [HttpGet("statuses")]public async Task<ActionResult> Statuses(CancellationToken t)=>Ok(await service.Statuses(t));[HttpPost("statuses")]public async Task<ActionResult> Status(SavePickupStatusRequest r,CancellationToken t)=>await Run(()=>service.CreateStatus(r.Command(),t));
 [HttpGet("vehicles")]public async Task<ActionResult> Vehicles(CancellationToken t)=>Ok(await service.Vehicles(t));[HttpPost("vehicles")]public async Task<ActionResult> Vehicle(SaveVehicleRequest r,CancellationToken t)=>await Run(()=>service.CreateVehicle(r.Command(),t));
 [HttpGet]public async Task<ActionResult> List(CancellationToken t)=>Ok(await service.List(t));[HttpPost]public async Task<ActionResult> Create(SavePickupRequest r,CancellationToken t)=>await Run(()=>service.Create(r.Command(),t));[HttpGet("{id:guid}")]public async Task<ActionResult> Get(Guid id,CancellationToken t){var x=await service.Get(id,t);return x is null?NotFound():Ok(x);}[HttpPut("{id:guid}/details")]public async Task<ActionResult> Details(Guid id,SavePickupDetailRequest r,CancellationToken t)=>await RunNullable(()=>service.SaveDetails(id,r.Command(),t));[HttpPost("{id:guid}/transactions")]public async Task<ActionResult> Transaction(Guid id,AddPickupTransactionRequest r,CancellationToken t)=>await RunNullable(()=>service.AddTransaction(id,r.Command(),t));
 [HttpPost("{id:guid}/confirmation-link")]public async Task<ActionResult> Link(Guid id,PickupLinkRequest r,CancellationToken t){try{var x=await service.Link(id,r.ValidDays,t);var baseUrl=links.BaseUrl;return Ok(new{url=$"{baseUrl}/pickup/{x.Token}",x.ExpiresAtUtc});}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}}
 private async Task<ActionResult> Run<T>(Func<Task<T>> f){try{return Ok(await f());}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}}private async Task<ActionResult> RunNullable<T>(Func<Task<T?>> f)where T:class{try{var x=await f();return x is null?NotFound():Ok(x);}catch(InvalidOperationException e){return BadRequest(new{message=e.Message});}}
}
